#!/bin/zsh
# Check, then deploy to production. Run from anywhere: zsh scripts/deploy.sh
# Nothing ships unless types, lint and every test pass.
set -e
cd "${0:A:h}/.."

# Types generated by a dev server go stale and fail the type check.
rm -rf .next/dev
npx tsc --noEmit -p .
npx eslint lib scripts app components
npm test --silent
vercel deploy --prod --yes
